package com.leetcode;

public class FindtheDifference {
    public static void main(String[] args) {
//        System.out.printf("%c%n", findTheDifference("abcd", "abcde"));
//        System.out.printf("%c%n", findTheDifference("", "a"));
//        System.out.printf("%c%n", findTheDifference("a", "aa"));
//        System.out.printf("%c%n", findTheDifference("ae", "aea"));
        String a = "";
        String b = "";
        System.out.printf("%c%n", findTheDifference2(a, b));
    }

    static char findTheDifference(String s, String t) {
        int sum = 0;
        int i = 0;
        while (i < s.length()) {
            sum+=t.charAt(i)-s.charAt(i);
            i++;
        }
        sum+=t.charAt(i);
        return (char)sum;
    }
    static char findTheDifference2(String s, String t) {
        int ans=0;
        int i;
        for(i=0;i<s.length();i++)
        {
            ans+=t.charAt(i)-s.charAt(i);
        }
        ans+=t.charAt(i);
        return (char)ans;
    }

    static char findTheDifference1(String s, String t) {
        if(s.length()==0)
            return t.charAt(0);
        int ans=s.charAt(0)^t.charAt(0);
        int i;
        for(i=1;i<s.length();i++)
        {
            ans=ans^(s.charAt(i)^t.charAt(i));
        }
        ans^=t.charAt(i);
        return (char)ans;
    }
}
